function countChangingNumbers(n: number): number {
  let count = 0;
  for (let x = 1; x <= n; x++) {
    let v = x, valid = true, changes = false;
    while (v > 0) {
      const d = v % 10;
      if (d === 3 || d === 4 || d === 7) { valid = false; break; }
      if (d === 2 || d === 5 || d === 6 || d === 9) changes = true;
      v = Math.floor(v / 10);
    }
    if (valid && changes) count++;
  }
  return count;
}

