function countChangingNumbers(n: number): number {
  const countUpTo = (allowed: number[]): number => {
    const digits = String(n).split("").map(Number);
    let total = 0;
    for (let i = 0; i < digits.length; i++) {
      const rest = digits.length - 1 - i;
      const smaller = allowed.filter(a => a < digits[i]).length;
      total += smaller * allowed.length ** rest;
      if (!allowed.includes(digits[i])) return total;
    }
    return total + 1; // n itself uses only allowed digits
  };
  return countUpTo([0, 1, 2, 5, 6, 8, 9]) - countUpTo([0, 1, 8]);
}

