        def count_up_to(allowed):
            digits = [int(c) for c in str(n)]
            total = 0
            for i, d in enumerate(digits):
                rest = len(digits) - 1 - i
                total += sum(1 for a in allowed if a < d) * len(allowed) ** rest
                if d not in allowed:
                    return total
            return total + 1

        return count_up_to([0, 1, 2, 5, 6, 8, 9]) - count_up_to([0, 1, 8])

